using System; using System.Collections.Generic; using System.Linq; using System.Text.Json; using System.Threading; using System.Threading.Tasks; using Parcs.Agent.Runtime;

public class State
{
    public double Lo { get; set; }
    public double Hi { get; set; }
    public long Count { get; set; }
}

public class Step : IAgentComputation
{
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        const long M = 16777216;
        const long K = 5000000;
        double lo = 0.0, hi = 1.0;
        var prev = input.GetPreviousOutputs();
        if (prev != null && prev.Length > 0)
        {
            long total = 0;
            State first = null;
            foreach (var s in prev)
            {
                if (s == null) continue;
                var x = JsonSerializer.Deserialize<State>(s);
                if (first == null) first = x;
                total += x.Count;
            }
            lo = first.Lo; hi = first.Hi;
            double oldMid = (lo + hi) / 2.0;
            if (total >= K) hi = oldMid; else lo = oldMid;
        }
        double mid = (lo + hi) / 2.0;
        long count = 0;
        unchecked
        {
            for (long i = input.WorkerIndex + 1; i <= M; i += input.TotalWorkers)
            {
                ulong z = (ulong)i * 0x9E3779B97F4A7C15UL;
                z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
                z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
                z = z ^ (z >> 31);
                double v = (double)(z % 2147483647UL) / 2147483647.0;
                if (v <= mid) count++;
            }
        }
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new State { Lo = lo, Hi = hi, Count = count })));
    }
}

public class Final : IAgentComputation
{
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        const long K = 5000000;
        var prev = input.GetPreviousOutputs();
        long total = 0; State first = null;
        foreach (var s in prev)
        {
            if (s == null) continue;
            var x = JsonSerializer.Deserialize<State>(s);
            if (first == null) first = x;
            total += x.Count;
        }
        double lo = first.Lo, hi = first.Hi;
        double mid = (lo + hi) / 2.0;
        if (total >= K) hi = mid; else lo = mid;
        double answer = (lo + hi) / 2.0;
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new { midpoint = answer })));
    }
}

